/**
 * The single place agent run status is derived for consumers: every emitted event carries the status the
 * conversation holds right now. Handlers call `transitionConversationStatus` before they emit, so provider
 * traffic during a pending question or approval reports `waitingForInput` instead of `running`.
 */
function emitRunEvent(run, event) {
    if (!run.onEvent) return;

    // `agentEvent` carries the timer too so the chat log tooltip stays fresh during a long
    // uninterrupted run, when no status transition happens to publish it.
    const timer = event.type === 'state' || event.type === 'agentEvent' ? run.conversation.timer : undefined;
    run.onEvent({ ...event, ...(timer ? { timer } : {}), runId: run.id, status: run.conversation.status });
}

function hasPendingInteraction(run) {
    return run.waitingForQuestion || run.pendingApprovals.size > 0;
}

function writeJsonLine(stream, message) {
    return new Promise((resolve, reject) => {
        stream.write(`${JSON.stringify(message)}\n`, (error) => {
            if (error) {
                reject(error);
                return;
            }

            resolve();
        });
    });
}

/**
 * The mutable state for one agent turn. `AgentRunnerService` keeps these in `processes` keyed by run id,
 * and `persistCheckpoint` spreads the whole object into the persistence layer, so the field set is a contract.
 */
function createRun({
    agent,
    child,
    conversation,
    environment,
    executable,
    id,
    nextSequence,
    onComplete,
    onCompletionError,
    onEvent,
    reference,
    request,
    rootPath,
    startedAt,
    streaming,
}) {
    const { promise: closed, resolve: resolveClosed } = Promise.withResolvers();
    const lastEntry = request.conversation?.entries.at(-1);
    const restoredQuestions = request.compactOnly && request.conversation.status === 'waitingForInput'
        && lastEntry?.kind === 'event' && lastEntry.type === 'agentQuestion' ? lastEntry.questions : null;

    return {
        providerEventEntryIndexes: createProviderEventEntryIndexes(conversation.entries),
        agent,
        assistantItemIndex: 0,
        assistantItems: new Map(),
        cancelled: false,
        child,
        changedPaths: new Set(),
        closed,
        claudeUsageTracker: null,
        conversation,
        codexCacheErrorReported: false,
        currentAssistantEntryIndex: null,
        currentAssistantMessageId: null,
        environment,
        executable,
        finishForced: false,
        finishTimeout: null,
        id,
        missingSession: false,
        nextSequence,
        onComplete,
        onCompletionError,
        onEvent,
        interactionWrites: Promise.resolve(),
        liveTurnUsage: null,
        pendingQuestionRequestId: restoredQuestions?.length > 0 ? `restored:${conversation.id}` : null,
        pendingQuestions: restoredQuestions ?? [],
        restoredQuestions: restoredQuestions?.length > 0,
        pendingApprovals: new Map(),
        persistence: Promise.resolve(),
        phases: createPhaseTracker(),
        providerConversationId: null,
        protocolLines: null,
        protocolHandling: Promise.resolve(),
        reference,
        reportedProviderErrors: new Set(),
        resolveClosed,
        rootPath,
        secretValues: new Set(),
        request,
        stderr: '',
        stderrBuffer: '',
        stderrHandling: Promise.resolve(),
        finishing: false,
        stdout: '',
        startedAt,
        streaming,
        streamingFailure: null,
        turnStarted: false,
        turnIndex: 1,
        turnActive: streaming && !request.compactOnly,
        sessionReady: false,
        activeCompact: null,
        termination: null,
        suspended: false,
        turnUsage: null,
        waitingForQuestion: restoredQuestions?.length > 0,
    };
}

/**
 * Wires the run to its provider protocol: streaming runs get the adapter plus a JSONL line buffer,
 * batch runs get the one-shot protocol parser.
 */
function attachRunProtocol(run, {
    onCodexRuntimeEvent,
    onMalformedOutput,
    onProviderEvent,
    onStreamingEvent,
    onStreamingLine,
    providerConversationId,
    rootPath,
}) {
    const writeLine = (message) => writeJsonLine(run.child.stdin, message);
    const providerSession = run.conversation.providerSessions.find(({ agent, conversationId }) =>
        agent === run.agent && conversationId === providerConversationId);
    run.claudeUsageTracker = run.agent === 'claude'
        ? new ClaudeUsageTracker(providerConversationId, providerSession?.usageBaseline)
        : null;
    run.streamingAdapter = run.streaming
        ? createAgentStreamingAdapter(
            run.agent,
            writeLine,
            onStreamingEvent,
            rootPath,
            providerConversationId,
            onCodexRuntimeEvent,
            run.request.executionSettings,
            run.claudeUsageTracker,
            run.request.agentTaskTrackingEnabled === true,
            run.conversation.taskList,
        )
        : null;
    run.protocolLines = run.streaming ? new JsonLineBuffer(run.id, onStreamingLine) : null;
    run.parser = run.streaming
        ? null
        : createAgentProviderProtocolParser(
            run.agent,
            onProviderEvent,
            onMalformedOutput,
            rootPath,
            run.claudeUsageTracker,
            run.conversation.taskList,
        );

    return run;
}

function createRunResult(request, exitCode, run) {
    return {
        command: request.command,
        conversation: run.conversation,
        exitCode,
        missingSession: run.missingSession,
        prompt: request.prompt,
        reference: run.reference,
        runId: run.id,
        stderr: run.stderr,
        stdout: run.stdout,
        changedPaths: [...run.changedPaths],
        turnStarted: run.turnStarted,
    };
}

module.exports = {
    attachRunProtocol,
    createRun,
    createRunResult,
    emitRunEvent,
    hasPendingInteraction,
    writeJsonLine,
};

const AGENT_COMMIT_PATTERN = /Commit:\s+([0-9a-fA-F]{7,40})(?![0-9A-Za-z])/gmu;
const COMMIT_LINE_PATTERN = /^\[(.+?) ([0-9a-f]{7,40})\]/gmu;
const ROOT_COMMIT_SUFFIX = ' (root-commit)';

/** Parse every marked commit ID from agent stdout. */
export function extractAgentCommitIds(output) {
    return [...output.matchAll(AGENT_COMMIT_PATTERN)].map((match) => match[1]);
}

/** Parse every branch and commit from Git commit summary output. */
export function extractCommitSummaries(output) {
    return [...output.matchAll(COMMIT_LINE_PATTERN)].map((match) => {
        const branch = match[1].endsWith(ROOT_COMMIT_SUFFIX) ? match[1].slice(0, -ROOT_COMMIT_SUFFIX.length) : match[1];

        return { branch, commit: match[2] };
    });
}

